<script setup lang="ts">import{nextTick,ref,watch}from"vue";import{titleRepository}from"@/domain/repositories";import{libraryCopyRepository}from"@/domain/library/repository";import{createLibraryCopyForm,hasLibraryCopyErrors,validateLibraryCopyForm,type LibraryCopyErrors}from"@/domain/library/validation";import type{LibraryCopyRecord}from"@/domain/library/records";import type{TitleRecord}from"@/types/records";const props=defineProps<{open:boolean;copy:LibraryCopyRecord|null}>();const emit=defineEmits<{close:[];saved:[LibraryCopyRecord]}>();const form=ref(createLibraryCopyForm()),errors=ref<LibraryCopyErrors>({}),saving=ref(false),query=ref(""),results=ref<TitleRecord[]>([]),first=ref<HTMLInputElement|null>(null);let timer:ReturnType<typeof setTimeout>|undefined;watch(()=>[props.open,props.copy]as const,async([open,copy])=>{if(!open)return;form.value=createLibraryCopyForm(copy||undefined);errors.value={};query.value=copy?.expand?.titulo?.titulo||"";results.value=[];await nextTick();first.value?.focus()},{immediate:true});watch(query,value=>{if(timer)clearTimeout(timer);if(value.trim().length<2){results.value=[];return}timer=setTimeout(async()=>{const escaped=value.trim().replaceAll('"','\"');results.value=(await titleRepository.list({page:1,perPage:20,filter:`apagado = false && (titulo ~ "${escaped}" || titulo_original ~ "${escaped}")`,sort:"titulo"})).items},300)});function select(title:TitleRecord){form.value.titulo=title.id;query.value=`${title.titulo}${title.ano?` (${title.ano})`:""}`;results.value=[]}async function save(){errors.value=validateLibraryCopyForm(form.value);if(hasLibraryCopyErrors(errors.value))return;saving.value=true;try{const payload={titulo:form.value.titulo,localizacao:form.value.localizacao.trim(),emprestado:form.value.emprestado};const saved=props.copy?await libraryCopyRepository.update(props.copy.id,payload):await libraryCopyRepository.create(payload);emit("saved",saved)}finally{saving.value=false}}</script><template><Teleport to="body"><div v-if="open" class="dialog-backdrop" @click.self="!saving&&emit('close')"><section class="dialog-panel library-copy-edit" role="dialog" aria-modal="true" aria-labelledby="library-copy-title" @keydown.esc="!saving&&emit('close')"><form novalidate @submit.prevent="save"><div class="dialog-header"><div><p class="eyebrow">Biblioteca física</p><h2 id="library-copy-title">{{copy?'Editar exemplar':'Novo exemplar'}}</h2></div><button class="icon-button" type="button" aria-label="Fechar" :disabled="saving" @click="emit('close')">×</button></div><label class="form-field"><span>Título do catálogo *</span><input ref="first" v-model.trim="query" type="search" autocomplete="off" :aria-invalid="errors.titulo?'true':'false'" aria-describedby="library-copy-title-help"/><small id="library-copy-title-help">Escreve pelo menos 2 caracteres e escolhe um resultado.</small><small v-if="errors.titulo" class="field-error" role="alert">{{errors.titulo}}</small></label><ul v-if="results.length" class="library-title-results"><li v-for="title in results" :key="title.id"><button type="button" @click="select(title)"><strong>{{title.titulo}}</strong><span>{{title.ano||'Ano desconhecido'}}</span></button></li></ul><label class="form-field"><span>Localização</span><input v-model="form.localizacao" maxlength="200" placeholder="Ex.: Estante A, prateleira 2"/><small v-if="errors.localizacao" class="field-error">{{errors.localizacao}}</small></label><label class="check-field"><input v-model="form.emprestado" type="checkbox"/> Exemplar emprestado</label><div class="form-actions"><button class="button button-secondary" type="button" :disabled="saving" @click="emit('close')">Cancelar</button><button class="button button-primary" type="submit" :disabled="saving">{{saving?'A guardar…':'Guardar exemplar'}}</button></div></form></section></div></Teleport></template>
